package com.nur.quran.data.planner

import com.google.gson.Gson
import com.google.gson.JsonParser
import com.google.gson.reflect.TypeToken
import com.nur.quran.data.sync.mergeField
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Fixture generated by the actual web buildReadingPlanner/adjustPlannerPace functions. */
class WebPlannerAdjustmentFixtureTest {
    private val gson = Gson()
    private val fixture = JsonParser.parseString(File("src/test/resources/fixtures/web-adjusted-plan.json").readText()).asJsonObject
    private fun parsed(key: String) = requireNotNull(PlannerEngine.parseReadingPlan(fixture[key].toString(),gson))
    private fun allPages(plan: ReadingPlan) = plan.assignments.flatMap { day -> day.items.flatMap { (it.pageStart..it.pageEnd).toList() } }.sorted()

    @Test fun actualWebAdjustedScheduleParsesAndCanBeAdjustedAgainOnMobile() {
        val adjusted = parsed("adjusted")
        assertEquals((582..604).toList(),allPages(adjusted))
        assertEquals("Preserve this reflection",adjusted.assignmentReflections[1])
        assertEquals(583,adjusted.lastReadPage)
        for (days in listOf(3,8)) {
            val native = PlannerEngine.rebalancePlanner(adjusted,"custom_pace",days)
            assertEquals("Native adjustment lost web pages",(582..604).toList(),allPages(native))
            assertEquals(adjusted.assignmentReflections,native.assignmentReflections)
            assertEquals(native,PlannerEngine.parseReadingPlan(gson.toJson(native),gson))
        }
        assertEquals(2,PlannerEngine.parseReadingPlans("[${fixture["initial"]},${fixture["adjusted"]}]",gson).size)
    }

    @Test fun actualWebNumericRangeValuesAndOptionalItemIdsAreAcceptedDuringSync() {
        val type = object : TypeToken<Map<String,Any?>>() {}.type
        val initial: Map<String,Any?> = gson.fromJson(fixture["initial"],type)
        val adjusted: Map<String,Any?> = gson.fromJson(fixture["adjusted"],type)
        val merged = mergeField("planners",listOf(initial),listOf(adjusted)) as List<*>
        val plan = merged.single() as Map<*,*>
        assertEquals(101.0,(plan["assignmentsUpdatedAt"] as Number).toDouble(),0.0)
        assertEquals(adjusted["assignments"],plan["assignments"])
        assertEquals(adjusted["durationDays"],plan["durationDays"])
        assertEquals((582..604).toList(),allPages(requireNotNull(PlannerEngine.parseReadingPlan(gson.toJson(plan),gson))))
    }
}
